#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Sets up the test site (#130, ADR-0020) from render.yaml: Stripe, Google,
# Resend, Render, DNS on Vercel, the reset Action's secret, then checks it all
# works. Run from anywhere in the repo: scripts/setup-test-site.sh
#
# Values you paste are kept in ~/.config/empire-cleaning/test-site.env (only
# you can read it, outside the repo) so a re-run offers them back.

TOTAL_STAGES=10

cd "$(git rev-parse --show-toplevel)"

# on WSL without wslview or Windows on the PATH, open_url opens the Windows
# browser through explorer.exe (which exits 1 even when it worked)
if ! command -v wslview >/dev/null 2>&1 && [[ -x /mnt/c/Windows/explorer.exe ]]; then
  wslview() { /mnt/c/Windows/explorer.exe "$1" || true; }
fi
mkdir -p "$HOME/.config/empire-cleaning" && chmod 700 "$HOME/.config/empire-cleaning"
ENV_FILE="$HOME/.config/empire-cleaning/test-site.env"

APP=https://app.test.empirecleaningandpro.com
LANDING=https://test.empirecleaningandpro.com
SERVER=https://empire-test-server.onrender.com
OFFICE=empirecleaningproservices@gmail.com

# show "KEY" prints a saved value to copy into a form
show() { printf '    %s%-24s%s %s\n' "$BOLD" "$1" "$RESET" "${!1}"; }

# dev_value KEY prints KEY from dev's own packages/server/.env, if it's there
dev_value() { local ENV_FILE=packages/server/.env; _existing "$1" || true; }

# reuse_dev KEY... saves dev's values for KEYs as the test site's; fails if
# any is missing
reuse_dev() {
  local key value
  for key in "$@"; do
    value=$(dev_value "$key")
    [[ -n "$value" ]] || { warn "$key isn't in packages/server/.env"; return 1; }
    write_env "$key" "$value"
  done
}

# checked ask|ask_secret KEY "Prompt" REGEX "what it looks like" asks until
# the value has the right shape, so a paste that missed (or picked up stray
# keys) is caught here; a secret is echoed back masked
checked() {
  local how="$1" key="$2" prompt="$3" pattern="$4" shape="$5" value
  while :; do
    "$how" "$key" "$prompt"
    value="${!key}"
    if [[ "$value" =~ $pattern ]]; then
      [[ "$how" == ask_secret ]] &&
        note "got ${value:0:10}…${value: -4} (${#value} characters)"
      return
    fi
    warn "that isn't $shape (${#value} characters); paste it again"
    printf -v "$key" '%s' ""
  done
}

# fetch URL prints its body, or nothing if it can't be reached
fetch() { curl -fsS --max-time 20 "$1" 2>/dev/null || true; }

banner "Test site setup (#130)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
say "Render builds the test site from render.yaml on main, so PR #142 must be"
say "merged first, and gh must be signed in to set the reset Action's secret."
if ! gh auth status >/dev/null 2>&1; then
  warn "gh isn't signed in. Run: gh auth login, then re-run this wizard."
  exit 1
fi
if [[ "$(gh pr view 142 --json state -q .state 2>/dev/null)" != "MERGED" ]]; then
  warn "PR #142 isn't merged yet. Merge it, then re-run this wizard."
  exit 1
fi
printf '  %s✓%s gh signed in, PR #142 merged\n' "$GREEN" "$RESET"
note "Render costs about \$13 a month for this (a starter server and a small"
note "database); the two static sites are free."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Stripe: a sandbox for the test site"
say "The test site should have a Stripe sandbox of its own (#45). Until one can"
say "be made, it can share dev's: the server ignores payments it doesn't know,"
say "so neither sees the other's (dev's \`stripe listen\` just gets extra no-ops)."
STRIPE_SHARED=""
if confirm "Share dev's sandbox for now (its keys from packages/server/.env)?" &&
  reuse_dev STRIPE_PUBLISHABLE_KEY STRIPE_SECRET_KEY; then
  STRIPE_SHARED=1
  SKIPPED+=("a Stripe sandbox of the test site's own (#45): the test site shares dev's")
else
open_url "https://dashboard.stripe.com/"
step "Click the account picker (top left) → Switch to sandbox → Create sandbox."
step "Name it: Empire test site. Leave 'Copy live account to sandbox' on."
step "Click Create sandbox, and stay inside it (the banner says sandbox)."
step "Go to Developers → API keys (or search 'API keys')."
step "Copy the Publishable key (pk_test_…)."
checked ask STRIPE_PUBLISHABLE_KEY "Paste the publishable key:" '^pk_test_[A-Za-z0-9]+$' "a pk_test_ key"
step "Reveal the Secret key (sk_test_…) and copy it."
checked ask_secret STRIPE_SECRET_KEY "Paste the secret key:" '^sk_test_[A-Za-z0-9]+$' "an sk_test_ key"
write_env STRIPE_PUBLISHABLE_KEY "$STRIPE_PUBLISHABLE_KEY"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
fi
[[ "$STRIPE_SECRET_KEY" == sk_test_* ]] || warn "that secret key doesn't start sk_test_: is it a sandbox's?"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Stripe: the webhook"
say "Stripe tells the server when payments succeed or fail."
open_url "https://dashboard.stripe.com/webhooks"
if [[ -n "$STRIPE_SHARED" ]]; then
  step "In dev's sandbox (the one dev's keys are from): Create an event destination."
  note "It gets a signing secret of its own; dev's \`stripe listen\` one is unchanged."
else
  step "Still in the Empire test site sandbox: Create an event destination."
fi
step "Events from: Your account. Payload: Snapshot, API version 2026-09-30.endive."
step "Select these 5 events (search each name):"
note "      payment_intent.succeeded"
note "      payment_intent.payment_failed"
note "      setup_intent.succeeded"
note "      charge.refunded"
note "      charge.dispute.created"
step "Continue → Webhook endpoint → Continue. Endpoint URL:"
note "      $APP/api/payments/webhook"
step "Create it, then on its page Reveal the signing secret (whsec_…)."
checked ask_secret STRIPE_WEBHOOK_SECRET "Paste the signing secret:" '^whsec_[A-Za-z0-9+/=]+$' "a whsec_ signing secret"
write_env STRIPE_WEBHOOK_SECRET "$STRIPE_WEBHOOK_SECRET"
note "Stripe can't reach it until the site is up; stage 10 checks a delivery."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google: a sign-in client for the test site"
say "Continue with Google needs a client that knows the test site's address."
open_url "https://console.cloud.google.com/apis/credentials"
if confirm "Reuse dev's sign-in client (from packages/server/.env), adding the test address?" &&
  reuse_dev GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET; then
  step "Open dev's OAuth client (its ID starts ${GOOGLE_CLIENT_ID:0:12}…)."
  step "Authorized redirect URIs → Add URI, keeping the localhost one:"
  note "      $APP/api/auth/callback/google"
  step "Save. (Google can take a few minutes to apply it.)"
  SKIPPED+=("a Google sign-in client of the test site's own: it shares dev's")
else
step "Pick the same Google Cloud project dev's sign-in client is in."
step "Create credentials → OAuth client ID → Application type: Web application."
step "Name: Empire test site."
step "Authorized redirect URIs → Add URI:"
note "      $APP/api/auth/callback/google"
step "Create. Copy the Client ID and Client secret from the dialog now:"
note "      Google may not show the secret again once the dialog closes."
checked ask GOOGLE_CLIENT_ID "Paste the client ID:" '^[0-9]+-[a-z0-9]+\.apps\.googleusercontent\.com$' "a …apps.googleusercontent.com client ID"
checked ask_secret GOOGLE_CLIENT_SECRET "Paste the client secret:" '^GOCSPX-[A-Za-z0-9_-]+$' "a GOCSPX- client secret"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
fi
note "If the consent screen's audience is still 'Testing', only its listed test"
note "users can sign in with Google; emailed sign-in links work for anyone."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Resend: an API key for the test site"
say "The test site sends from test@empirecleaningandpro.com, on the Resend"
say "account dev uses now (the one with the domain verified)."
open_url "https://resend.com/domains"
step "Check empirecleaningandpro.com shows Verified. (If not, stop here: #63.)"
pause "Verified? Press Enter"
if confirm "Reuse dev's API key (from packages/server/.env)?" &&
  reuse_dev RESEND_API_KEY; then
  SKIPPED+=("a Resend API key of the test site's own: it shares dev's")
else
open_url "https://resend.com/api-keys"
step "Create API key → Name: Empire test site → Permission: Sending access,"
step "Domain: empirecleaningandpro.com → Add. Copy the key (re_…): it's shown once."
checked ask_secret RESEND_API_KEY "Paste the API key:" '^re_[A-Za-z0-9_]+$' "an re_ API key"
write_env RESEND_API_KEY "$RESEND_API_KEY"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Render: create the test site from render.yaml"
open_url "https://dashboard.render.com/"
step "Sign up or sign in (Sign in with GitHub is simplest). If asked, add a card."
step "New → Blueprint. Connect GitHub if asked, giving Render access to"
step "CristianCrane/empire-cleaning, then click Connect next to that repo."
step "Blueprint name: Empire test site. Branch: main. Path: render.yaml."
step "Render lists 4 resources and asks for these 6 values; paste each:"
show RESEND_API_KEY
show GOOGLE_CLIENT_ID
show GOOGLE_CLIENT_SECRET
show STRIPE_SECRET_KEY
show STRIPE_PUBLISHABLE_KEY
show STRIPE_WEBHOOK_SECRET
step "Click Deploy Blueprint, and wait for empire-test-server to show Live"
step "(the first build takes a few minutes)."
note "Render asks for these only now; to change one later, edit it on the"
note "service's Environment page."
pause "Is empire-test-server Live? Press Enter"
say "Its address must be $SERVER: the web app's /api rewrite points there."
until [[ "$(fetch "$SERVER/health")" == *'"ok"'* ]]; do
  warn "$SERVER/health isn't answering."
  note "Check the address at the top of empire-test-server's page in Render."
  note "If it's different (e.g. a suffix was added), stop and update the"
  note "rewrite in render.yaml to match, then re-run."
  confirm "Try again?" || exit 1
done
printf '  %s✓%s the server answers at %s\n' "$GREEN" "$RESET" "$SERVER"
if [[ "$(fetch "$SERVER/api/site")" != *'"test"'* ]]; then
  warn "but it isn't in test mode: check APP_MODE=test on its Environment page."
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "DNS on Vercel: the two test addresses"
say "Point the test addresses at Render's static sites."
open_url "https://vercel.com/dashboard/domains"
step "Open empirecleaningandpro.com → DNS Records, and add two records:"
note "      Name: test      Type: CNAME   Value: empire-test-landing.onrender.com"
note "      Name: app.test  Type: CNAME   Value: empire-test-web.onrender.com"
step "If either name already has an AAAA record, delete it (Render is IPv4 only)."
pause "Added? Press Enter"
open_url "https://dashboard.render.com/"
step "In Render, open empire-test-landing → Settings → Custom Domains, and click"
step "Verify next to test.empirecleaningandpro.com. Do the same on"
step "empire-test-web for app.test.empirecleaningandpro.com."
step "Wait for both to show their certificate issued (it can take a few minutes)."
pause "Both verified with HTTPS? Press Enter"
until [[ "$(fetch "$APP/api/site")" == *'"test"'* ]]; do
  warn "$APP/api/site doesn't answer {\"mode\":\"test\"} yet."
  note "DNS or the certificate may still be on its way: wait a minute. If it"
  note "answers with the web app's page instead, the /api rewrite isn't working."
  confirm "Try again?" || exit 1
done
printf '  %s✓%s %s/api reaches the server through the rewrite\n' "$GREEN" "$RESET" "$APP"
until [[ "$(fetch "$LANDING/robots.txt")" == *"Disallow: /"* ]]; do
  warn "$LANDING doesn't answer as the test landing site yet."
  confirm "Try again?" || exit 1
done
printf '  %s✓%s %s is up, and closed to search engines\n' "$GREEN" "$RESET" "$LANDING"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "GitHub: the test database for the reset Action"
say "The Reset test data Action connects to the database from GitHub."
open_url "https://dashboard.render.com/"
step "Open empire-test-db → Connect (top right) → External."
step "Copy the External Database URL (postgresql://…)."
checked ask_secret TEST_DB_URL "Paste the external database URL:" '^postgres(ql)?://[^[:space:]]+$' "a postgresql:// URL"
# Render requires TLS from outside, which the pg driver asks for this way
TEST_DB_URL="${TEST_DB_URL%%\?*}?sslmode=require"
write_env TEST_DB_URL "$TEST_DB_URL"
set_secret TEST_DB_URL "$TEST_DB_URL"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Seed the test data"
say "Running the Reset test data Action puts the dev seed on the test site."
if confirm "Run it now? (it replaces everything but Accounts and the Price List)"; then
  gh workflow run reset-test-data.yml --ref main
  note "waiting for the run to start…"
  sleep 8
  run_id=$(gh run list --workflow=reset-test-data.yml --limit 1 --json databaseId -q '.[0].databaseId')
  if gh run watch "$run_id" --exit-status; then
    printf '  %s✓%s seeded\n' "$GREEN" "$RESET"
  else
    warn "the run failed; read it with: gh run view $run_id --log-failed"
