# ── 10 ────────────────────────────────────────────────────────────────────
stage "Check it all works"
say "Sign-in as the Office:"
open_url "$APP/sign-in"
step "Ask for a sign-in link for $OFFICE."
step "It arrives with [TEST] at the start of the subject. Sign in: the banner"
step "shows, and the Office's screens have the seed data."
pause "Signed in? Press Enter"
say "A test card payment and its webhook:"
step "Sign out, then sign in as empirecleaningproservices+sam@gmail.com (Sam Ng,"
step "who has a Sent Quote). Accept it and pay the deposit with card"
note "      4242 4242 4242 4242, any future date, any CVC and ZIP."
open_url "https://dashboard.stripe.com/webhooks"
step "In the sandbox's webhook → Event deliveries, the events show Delivered (200)."
pause "Paid and delivered? Press Enter"
say "An email to someone not allowed goes to the Office inbox instead:"
open_url "$LANDING/#quote"
step "Request a Quote as a Guest with a made-up email, e.g. someone@example.com."
step "The Office inbox gets '[TEST → someone@example.com] …' (the Quote receipt)."
note "This also shows the landing form reaches the API."
pause "Arrived? Press Enter"
if confirm "Did all three work?"; then
  printf '  %s✓%s #130 is done: tick its boxes and close it\n' "$GREEN" "$RESET"
else
  SKIPPED+=("a check failed: note which in #130 and bring it back to Claude")
fi
pause

finish
}

run_wizard "$@"; exit
